import{analyze,catalog,sources,VERSION}from'./engine.js';
const $=id=>document.getElementById(id),escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let medicines=[],report=null,snapshot=null,file=null,fileUrl=null,ocrBusy=false,epoch=0;
const emptyResults=$('results').innerHTML;
const options=(values,current)=>values.map(([v,label])=>`<option value="${v}" ${String(current)===v?'selected':''}>${label}</option>`).join('');
const blank=()=>({id:crypto.randomUUID(),name:'',strength:'',unit:'mg',quantity:'',schedule:'',route:'oral',form:'tablet',status:'current',confirmed:false});
function renderMedicines(){$('medicines').innerHTML=medicines.map((m,i)=>`<section class="medicine" data-id="${m.id}" aria-label="Medicine ${i+1}"><div class="med-head"><label>Medicine ${i+1} · active ingredient<input data-key="name" list="med-options" value="${escape(m.name)}" placeholder="e.g. paracetamol" maxlength="120"></label><button class="remove" data-remove="${m.id}" aria-label="Remove medicine ${i+1}">×</button></div><div class="med-grid"><label>Strength per tablet<input data-key="strength" type="number" min="0.001" max="100000" step="any" value="${escape(m.strength)}" placeholder="e.g. 500"></label><label>Strength unit<select data-key="unit">${options([['mg','mg'],['g','g'],['mcg','micrograms']],m.unit)}</select></label><label>Tablets per dose<input data-key="quantity" type="number" min="0.01" max="100" step="any" value="${escape(m.quantity)}" placeholder="e.g. 1"></label><label>How often?<select data-key="schedule">${options([['','Choose schedule'],['1','Once a day'],['2','Twice a day'],['3','3 times a day'],['4','4 times a day'],['weekly','Once a week'],['needed','Only when needed'],['other','Other / not sure']],m.schedule)}</select></label><label>Form<select data-key="form">${options([['tablet','Tablet'],['capsule','Capsule'],['other','Liquid / other']],m.form)}</select></label><label>How it is taken<select data-key="route">${options([['oral','By mouth'],['other','Other route']],m.route)}</select></label><label>Current use<select data-key="status">${options([['current','Currently taking'],['stopped','Stopped'],['historical','Past prescription'],['uncertain','Not sure']],m.status)}</select></label></div><label class="confirm"><input type="checkbox" data-key="confirmed" ${m.confirmed?'checked':''}> I checked the ingredient, strength, amount, form, route and timing against the prescription.</label></section>`).join('');}
function invalidate(){if(!report)return;report=null;snapshot=null;$('results').innerHTML='<div class="eyebrow">DETAILS CHANGED</div><div class="stale">Your previous report is out of date. Run the check again to include your changes.</div>'+emptyResults;}
function context(){return{age:$('age').value,allergyStatus:$('allergy-status').value,allergies:$('allergies').value,reaction:$('reaction').value,historyConfirmed:$('history-confirmed').checked,kidney:$('kidney').checked,ulcer:$('ulcer').checked,liver:$('liver').checked,pregnancy:$('pregnancy').checked};}
function showReport(){const r=report;const count=r.findings.length;$('results').innerHTML=`<div class="report-top"><div class="eyebrow">YOUR REVIEW</div><span class="micro">Limited screening</span></div><div class="count">${count}</div><h3>${count===1?'potential concern':count?'potential concerns':'flags in the selected checks'}</h3><p><strong>${count?'Take these questions to your pharmacist.':'No flags does not mean no risk.'}</strong> ${escape(r.status)}.</p><p class="micro">${r.activeCount} current medicine(s) · ${r.excludedCount} other entries excluded. Uncertain use is not checked; confirm it with your pharmacist.</p>${r.findings.map(f=>`<article class="finding ${f.level}"><span class="severity">${f.level==='priority'?'! Prompt professional review':'↗ Discuss with your pharmacist'}</span><h4>${escape(f.title)}</h4><p class="trigger">${escape(f.trigger)}</p><p>${escape(f.explanation)}</p><p class="action">${escape(f.action)}</p>${f.source?`<a href="${f.source}" target="_blank" rel="noopener noreferrer">Read the reference ↗</a>`:'<span class="micro">Based on your entries; not independently verified.</span>'}<div class="micro">Demo rule: ${escape(f.id)} · Not clinically validated</div></article>`).join('')}<div class="coverage"><details open><summary>What still needs checking (${r.gaps.length})</summary><ul>${r.gaps.map(g=>`<li>${escape(g)}</li>`).join('')}</ul></details></div><p class="micro">Prepared ${escape(new Date(r.createdAt).toLocaleString())}<br>Rule version ${VERSION} · No professional has reviewed this report.</p><div class="report-actions"><button id="print" class="secondary">Print / save PDF ↗</button><button id="download" class="secondary">Download report ↓</button></div><div class="soft-note">Your report stays here until you change details, clear the session, or close this page. Nothing is sent to a care team.</div>`;$('print').onclick=()=>window.print();$('download').onclick=download;}
function download(){if(!report)return;const text=['ScriptCheck — educational prototype',report.status,`Created: ${report.createdAt}`,`Rules: ${report.version}`,'No professional has reviewed this report. Do not change treatment based on it.','',...snapshot.medicines.map(m=>`${m.name}: ${m.strength} ${m.unit}, ${m.quantity} unit(s), schedule ${m.schedule}, ${m.form}, ${m.route}, ${m.status}; details confirmed: ${m.confirmed}`),'',`Reported age: ${snapshot.context.age||'unknown'}`,`Allergy status: ${snapshot.context.allergyStatus}; ${snapshot.context.allergies}; reaction: ${snapshot.context.reaction}`,`Reported context: ${['kidney','ulcer','liver','pregnancy'].filter(k=>snapshot.context[k]).join(', ')||'none selected (not independently verified)'}`,'',...report.findings.flatMap(f=>[f.title,f.trigger,f.explanation,f.action,f.source||'Based on entered history.','']),'UNRESOLVED LIMITS',...report.gaps].join('\n');const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='scriptcheck-review.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('med-options').innerHTML=catalog.map(n=>`<option value="${n}"></option>`).join('');$('coverage-list').textContent=catalog.join(' · ');$('sources').innerHTML=Object.entries(sources).map(([name,url])=>`<a href="${url}" target="_blank" rel="noopener noreferrer">${name==='paracetamol'?'FDA':'NHS'} · ${name} ↗</a>`).join('');
$('add').onclick=()=>{invalidate();medicines.push(blank());renderMedicines();$('medicines').lastElementChild.querySelector('input').focus();};
$('medicines').addEventListener('input',e=>{const row=e.target.closest('[data-id]');if(!row||!e.target.dataset.key)return;invalidate();const m=medicines.find(m=>m.id===row.dataset.id),key=e.target.dataset.key;m[key]=e.target.type==='checkbox'?e.target.checked:e.target.value;if(key!=='confirmed'){m.confirmed=false;row.querySelector('[data-key="confirmed"]').checked=false;}});
$('medicines').addEventListener('click',e=>{const id=e.target.closest('[data-remove]')?.dataset.remove;if(id){invalidate();medicines=medicines.filter(m=>m.id!==id);renderMedicines();}});
for(const id of ['age','allergy-status','allergies','reaction','history-confirmed','kidney','ulcer','liver','pregnancy','prescription-text'])$(id).addEventListener('input',invalidate);
$('allergy-status').addEventListener('change',()=>{$('allergy-fields').hidden=$('allergy-status').value!=='known';});
$('analyze').onclick=()=>{const active=medicines.filter(m=>m.status==='current');if(!active.length){$('form-message').textContent='Add at least one current medicine before checking.';return;}if(active.some(m=>!m.name.trim())){$('form-message').textContent='Enter a name for each current medicine.';return;}if(active.some(m=>!m.confirmed)){$('form-message').textContent='Compare each current medicine with the prescription, then tick its confirmation box. If unsure, ask a pharmacist.';return;}if($('age').value&&!$('age').checkValidity()){$('form-message').textContent='Enter an age between 1 and 120, or leave it blank.';return;}if([...$('medicines').querySelectorAll('input[type=number]')].some(x=>x.value&&!x.checkValidity())){$('form-message').textContent='Check the medicine amounts. Enter positive numbers, or leave unknown amounts blank.';return;}$('form-message').textContent='';snapshot={medicines:structuredClone(medicines),context:context()};report=analyze(snapshot.medicines,snapshot.context);showReport();$('results').scrollIntoView({behavior:'smooth',block:'start'});};
function clearFile(){epoch++;file=null;if(fileUrl)URL.revokeObjectURL(fileUrl);fileUrl=null;$('preview').replaceChildren();$('file-info').textContent='';$('file').value='';$('ocr').hidden=true;}
$('file').onchange=async()=>{const selected=$('file').files[0];if(!selected)return;clearFile();invalidate();if(selected.size>10*1024*1024){$('file-info').textContent='This file is too large. Choose a file smaller than 10 MB.';return;}if(!['image/jpeg','image/png','image/webp','application/pdf','text/plain'].includes(selected.type)){$('file-info').textContent='Please choose a JPG, PNG, WEBP, PDF or plain text file.';return;}file=selected;fileUrl=URL.createObjectURL(file);$('file-info').textContent=`${file.name} · on this device only`;
 if(file.type.startsWith('image/')){const img=document.createElement('img');img.src=fileUrl;img.alt='Your uploaded prescription — check the details manually';$('preview').append(img);$('ocr').hidden=false;}
 else if(file.type==='application/pdf'){const frame=document.createElement('iframe');frame.src=fileUrl;frame.title='Prescription PDF preview';$('preview').append(frame);const link=document.createElement('a');link.href=fileUrl;link.target='_blank';link.rel='noopener';link.textContent='Open PDF for manual transcription ↗';$('preview').append(link);$('file-info').textContent+=' · PDF text is not automatically extracted.';}
 else{const run=epoch;const text=await file.text();if(run===epoch){$('prescription-text').value=text.slice(0,10000);$('file-info').textContent+=' · Confirm each medicine below; notes are not analyzed.';}}
};
$('ocr').onclick=async()=>{if(!file||ocrBusy)return;ocrBusy=true;const run=epoch,input=file;$('ocr').disabled=true;$('file-info').textContent='Loading on-device text reader. Your photo is not uploaded.';let worker;try{const{createWorker}=await import('https://cdn.jsdelivr.net/npm/tesseract.js@5.1.1/dist/tesseract.esm.min.js');worker=await createWorker('eng');const{data}=await worker.recognize(input);if(run===epoch){invalidate();$('prescription-text').value=data.text.slice(0,10000);$('file-info').textContent='Draft text ready. Check every name and number; enter the confirmed medicines below.';}}catch{if(run===epoch)$('file-info').textContent='Text reading could not finish. You can still view the photo and enter each medicine manually.';}finally{if(worker)await worker.terminate();ocrBusy=false;$('ocr').disabled=false;}};
$('clear').onclick=()=>{clearFile();medicines=[blank()];report=null;snapshot=null;renderMedicines();for(const id of['age','allergies','reaction','prescription-text'])$(id).value='';for(const id of['kidney','ulcer','liver','pregnancy','history-confirmed'])$(id).checked=false;$('allergy-status').value='unknown';$('allergy-fields').hidden=true;$('results').innerHTML=emptyResults;$('form-message').textContent='Session cleared.';};
$('demo').onclick=()=>{$('clear').click();medicines=[{...blank(),name:'warfarin',strength:'5',quantity:'1',schedule:'1',confirmed:true},{...blank(),name:'ibuprofen',strength:'400',quantity:'1',schedule:'3',confirmed:true}];$('age').value='45';$('allergy-status').value='none';$('history-confirmed').checked=true;renderMedicines();$('form-message').textContent='Example only — these are fictional entries, not recommended doses.';$('checker').scrollIntoView({behavior:'smooth'});};
medicines=[blank()];renderMedicines();
